function cleanName(name){
 return name
  .toLowerCase()
  .replace(/[^a-z0-9]/g,"_")
  .replace(/_+/g,"_")
  .replace(/^_|_$/g,"")
}

function detectType(values){
 for(const v of values){

  if(v === null || v === "") continue

  const val = String(v).toLowerCase()

  if(val === "true" || val === "false")
   return "BOOLEAN"

  if(!isNaN(val) && Number.isInteger(Number(val)))
   return "INTEGER"

  if(!isNaN(val))
   return "NUMERIC"

  if(/^\d{4}[-/]\d{2}[-/]\d{2}/.test(val))
   return "DATE"
 }

 return "TEXT"
}

// ambil data dari node sebelumnya
let rows = $input.first().json.cleaned_rows
let columns = $('Set Text (Flow Merged)').first().json.column_names
const table = $('AI Agent Labelling').first().json.output.table_name

// normalisasi rows
if(typeof rows === "string"){
 rows = JSON.parse(rows)
}

if(!Array.isArray(rows)){
 rows = [rows]
}

// normalisasi column_names
if(typeof columns === "string"){
 columns = JSON.parse(columns)
}

// generate schema
let columnSQL = []
let indexSQL = []
for(const col of columns){
 const clean = cleanName(col)
 const values = rows.map(r => r[col])
 const type = detectType(values)
 columnSQL.push(`${clean} ${type} NULL`)
 if(type !== "TEXT"){
  indexSQL.push(
   `CREATE INDEX IF NOT EXISTS idx_${table}_${clean} ON public.${table} (${clean});`
  )
 }
}

// index penting untuk foreign key
indexSQL.push(
 `CREATE INDEX IF NOT EXISTS idx_${table}_record_manager_id ON public.${table} (record_manager_id);`
)

// CREATE TABLE
const createTableSQL = `
CREATE TABLE IF NOT EXISTS public.${table} (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 record_manager_id BIGINT NULL,
 ${columnSQL.join(",\n")},
 created_at TIMESTAMPTZ DEFAULT now(),
 CONSTRAINT ${table}_pkey PRIMARY KEY (id),
 CONSTRAINT ${table}_record_manager_id_fkey
 FOREIGN KEY (record_manager_id)
 REFERENCES record_manager(id)
 ON DELETE CASCADE

);
`

// ENABLE RLS
const rlsSQL = `
ALTER TABLE public.${table}
ENABLE ROW LEVEL SECURITY;
`

// POLICY SELECT
const policyReadSQL = `
CREATE POLICY IF NOT EXISTS "policy_read_${table}"
ON public.${table}
FOR SELECT
USING (true);
`

// POLICY INSERT
const policyInsertSQL = `
CREATE POLICY IF NOT EXISTS "policy_insert_${table}"
ON public.${table}
FOR INSERT
WITH CHECK (true);
`

return [{
 json:{
  create_sql:createTableSQL,
  index_sql:indexSQL.join("\n"),
  rls_sql: rlsSQL,
  policy_read_sql: policyReadSQL,
  policy_insert_sql: policyInsertSQL,
  table_name:table
 }
}]

function cleanName(name){
 return name
  .toLowerCase()
  .replace(/[^a-z0-9]/g,"_")
  .replace(/_+/g,"_")
  .replace(/^_|_$/g,"")
}

function sqlValue(v){
 if(v === null) return "NULL"
 if(typeof v === "boolean") return v ? "TRUE" : "FALSE"
 if(typeof v === "number") return v
 return `'${v}'`
}

const rows = $('Cleaning Tabular Data').first().json.cleaned_rows

const table = $('AI Agent Labelling').first().json.output.table_name

const recordManagerId = $('Create Row in Record Manager').first().json.id

const columns = Object.keys(rows[0])

const cleanColumns = columns.map(c => cleanName(c))

// tambahkan kolom record_manager_id
const finalColumns = [...cleanColumns, "record_manager_id"]

let valuesSQL = []

for(const row of rows){

 const values = columns.map(c => sqlValue(row[c]))

 // tambahkan value record_manager_id di setiap row
 values.push(sqlValue(recordManagerId))

 valuesSQL.push(`(${values.join(",")})`)
}

const insertSQL = `
INSERT INTO public.${table}
(${finalColumns.join(",")})
VALUES
${valuesSQL.join(",\n")}
;
`

return [{
 json:{
  insert_sql: insertSQL
 }
}]

function excelDateToISO(serial){
 if(typeof serial !== "number") return serial
 if(serial < 40000 || serial > 50000) return serial
 const excelEpoch = new Date(Date.UTC(1899,11,30))
 const date = new Date(excelEpoch.getTime() + serial*86400000)
 return date.toISOString().slice(0,10)
}

function cleanString(value){
 if(value === null || value === undefined) return null
 if(typeof value !== "string") return value
 let v = value.trim()
 if(v === "") return null
 // escape single quote supaya aman di SQL
 v = v.replace(/'/g,"''")
 return v
}

function convertKompeten(value){
 if(value === null || value === undefined) return null
 const v = String(value).trim().toUpperCase()
 if(v === "K") return true
 if(v === "BK") return false
 return null
}

function cleanValue(value){
 if(value === "" || value === undefined) return null
 // Excel serial date
 if(typeof value === "number"){
  const converted = excelDateToISO(value)
  return converted
 }
 if(!isNaN(value) && Number(value) > 40000 && Number(value) < 50000){
  return excelDateToISO(Number(value))
 }
 return cleanString(value)
}

